"""Local, searchable handbook with current user bindings; no network requests."""
import html,re,sys
from pathlib import Path
from PySide6.QtCore import Qt
from PySide6.QtWidgets import QDialog,QVBoxLayout,QHBoxLayout,QLineEdit,QListWidget,QTextBrowser,QSplitter,QLabel,QTextEdit
from editor_chrome import heading,EDITOR_STYLE,action_button
from app_version import VERSION


def handbook(values,root):
    convert,edit,tools=(html.escape(values[name]) for name in ('convert_key','edit_key','files_key'));location=html.escape(str(root))
    sections = [
    ('Schnellstart',f'''<h2>In vier Schritten zur neuen Datei</h2><ol><li>Eine oder mehrere Dateien im Explorer mit der linken Maustaste ziehen.</li><li>Während des Ziehens <b>{convert}</b> für Konvertieren, <b>{edit}</b> für Bearbeiten oder <b>{tools}</b> für Tools kurz drücken.</li><li>Die Taste wieder loslassen und die Maustaste weiter gedrückt halten. OrbitDrop prüft die Auswahl und zeigt passende Aktionen.</li><li>Die Datei auf der gewünschten Aktion ablegen. Einstellungen öffnen sich bei Bedarf; anschließend läuft der Auftrag im Verlauf.</li></ol><p>Alternativ das OrbitDrop-Symbol im Windows-Infobereich anklicken und Dateien in den Kreis ziehen. Im Startkreis zwischen Konvertieren, Bearbeiten und Tools wählen. Nur nach dieser Menünavigation erscheint Zurück. Beim direkten Tastenzugang entfällt dieser zusätzliche Eintrag. Rechtsklick im Kreis öffnet die Aktionssuche. <b>Esc</b> schließt den Kreis.</p><p>Konvertierungen und Bearbeitungen erstellen normalerweise neue Dateien. <b>Verschieben und Umbenennen ändern dagegen die Originale.</b> Die Aktion und die Vorschau vor dem Ausführen prüfen.</p>'''),
    ('Bedienung & eigene Tasten',f'''<h2>Deine aktuelle Belegung</h2><table cellpadding="8"><tr><td><b>{convert}</b></td><td>Konvertieren · grün</td></tr><tr><td><b>{edit}</b></td><td>Bearbeiten · orange</td></tr><tr><td><b>{tools}</b></td><td>Tools · blau</td></tr></table><p>Die Bereiche können während des Ziehens gewechselt werden. Automatische Datei-Tastenzugänge gelten nur für Explorer, Desktop, OrbitDrop und unterstützte Dateimanager (Total Commander, Double Commander, Directory Opus, FreeCommander, Files). In anderen Apps und Spielen bleibt Shift/Strg/Alt plus Mausklick ohne automatischen Kreis. Dort den Kreis über das Tray öffnen und die Datei hineinziehen. Markierte Links werden aus Edge, Chrome, Firefox, Brave, Vivaldi, Opera, LibreWolf, Waterfox und Floorp außerhalb des Vollbilds übernommen; dazu die Maustaste loslassen. Im Tray pausiert „Tastenzugänge pausieren“ alle globalen Tastenzugänge bis zum Abschalten oder Neustart, auch für Browser-Spiele. Die manuelle Bedienung bleibt verfügbar. Ohne laufendes Ziehen liest nur die Konvertieren-Taste in unterstützten Browsern oder OrbitDrop eine ausdrücklich markierte Textauswahl, um einen Link anzubieten. Es wird dabei nichts automatisch heruntergeladen und die Zwischenablage wird nicht ersetzt.</p><p>Unter Einstellungen → Allgemein eine Taste eintippen oder im Aufnahmefeld drücken. Möglich sind Shift/Strg/Alt, Buchstaben, Ziffern (Num0–Num9 für den aktiven Nummernblock), F1–F24 sowie die dort unterstützten Navigationstasten, allein oder als Kombination mit Modifikatoren. Beispiele: F8, Strg+E, Shift+F9. Kombinationen werden durch gleichzeitiges Drücken ausgelöst.</p><p>Belegungen dürfen sich nicht enthalten: Shift und Shift+F9 wären mehrdeutig. Strg+Alt bleibt für AltGr reserviert. Esc, Win-Kombinationen und Alt+F4 sind nicht belegbar. OrbitDrop unterdrückt die ursprüngliche Windows-/Explorer-Funktion einer Taste nicht. In modalen OrbitDrop-Fenstern pausiert die globale Erkennung. Schnitt- und Textbearbeitungs-Tasten im Editor bleiben unverändert.</p><p>„Standardtasten wiederherstellen“ setzt Shift / Strg / Alt zurück; erst Speichern übernimmt die Änderungen.</p>'''),
    ('Menüs personalisieren & Favoriten','''<h2>Das Oktagon-Menü</h2><p>Alle Kacheln sind gleich große regelmäßige Oktagone. Häufige Aktionen stehen im inneren Ring auf festen Plätzen. „Weitere“ erweitert nach außen; „Weniger“ klappt den äußeren Ring wieder ein. Während des Ziehens etwa eine halbe Sekunde darauf halten, dann zur gewünschten Aktion weiterziehen. Bei vielen Aktionen wechseln „Nächste Seite“ und „Vorige Seite“ nur den äußeren Ring. Beim manuellen Wechsel aus der Startansicht reserviert Zurück einen inneren Platz.</p><p>Einstellungen → Allgemein → „Mit erweitertem Oktagon-Menü starten“ zeigt weitere Aktionen direkt beim Öffnen. Auf kleinen Arbeitsflächen öffnet „Weitere“ stattdessen nach dem Ablegen oder Anklicken die Aktionssuche.</p><h2>Nur die Funktionen zeigen, die du brauchst</h2><p>Einstellungen → <b>Menüpunkte</b>: Haken bedeutet anzeigen. Entferne Haken bei Formaten, Bearbeitungen, Dateiaktionen, Programmfunktionen, Downloads, eigenen Schnellaktionen oder Abläufen. Eine Gruppen-Checkbox schaltet alle Einträge der Gruppe, auch wenn die Suche einzelne Zeilen gerade ausblendet. Die Suche filtert nur die Anzeige.</p><p>SVG Schnell und SVG Erweitert sind einzeln steuerbar. Bereits früher ausgeblendete Formate werden übernommen. Ein zusätzlicher Favorit kann den fünften Platz im inneren Ring erhalten und trägt einen Stern; ein ausgeblendeter Favorit bleibt dennoch unsichtbar. Die Aktionssuche berücksichtigt ausgeblendete Einträge ebenfalls.</p><p>Die drei Kategorien der Startansicht lassen sich unter Bereichsauswahl ausblenden; ihre Tastenzugänge bleiben nutzbar. Direkt mit einer Bereichstaste oder über das Tray geöffnete Hauptbereiche haben keinen Zurück-Eintrag. Die Bereichstasten wechseln während des Ziehens zwischen den Hauptbereichen. Nach einer manuellen Menünavigation gibt es Zurück; dieser Eintrag lässt sich ausblenden. Esc schließt den Kreis. Das ist eine Anpassung der Anzeige, keine Zugriffssperre.</p><p>Falls du Einstellungen, Anleitung oder sämtliche Einträge ausgeblendet hast: <b>Rechtsklick auf das OrbitDrop-Symbol im Windows-Infobereich → Einstellungen</b>. „Alle Menüpunkte wieder anzeigen“ setzt die Anzeige zurück. Änderungen gelten nach Speichern beim nächsten Öffnen des Kreises.</p><p>Rechtsklick im Kreis → Aktionssuche: Dateien auswählen, einen Begriff wie „schneiden“ suchen und mit Enter öffnen. „Favorit setzen“ speichert die Aktion für später.</p>'''),
    ('Konvertieren & unterstützte Formate','''<h2>Zusatzprogramme prüfen</h2><p>Tools → Konverter erklärt, welche Funktionen verfügbar sind. LibreOffice und Pandoc sind optionale Zusatzprogramme für weitere Dokumentformate. Fehlende optionale Programme stören beim Start nicht. Die Prüfung läuft im Hintergrund; technische Pfade und Versionsausgaben findest du bei Bedarf unter Details. Bei fehlenden Medienwerkzeugen erklärt ein Hinweis, wie du sie über das OrbitDrop-Symbol neben der Uhr einrichtest.</p><h2>Passende Zielformate statt unpassender Optionen</h2><p>OrbitDrop prüft den Dateiinhalt und die vorhandenen Konverter. Bei mehreren Dateien werden nur gemeinsam passende Konvertierungen angeboten. Der innere Ring zeigt häufige Ziele. „Weitere“ öffnet die übrigen Ziele im äußeren Ring ohne weitere Format-Untermenüs. Ausgeblendete Formate bleiben entfernt.</p><p>Ergebnisse werden im eingestellten Ausgabeordner oder neben der Quelle gespeichert. Vorhandene Namen erhalten Nummernzusätze. Der Originaldatei wird bei normalen Konvertierungen nichts überschrieben. JPG kann keine Transparenz speichern; transparente Stellen werden weiß. Animationen und mehrseitige Bilder werden bei einfachen Bildkonvertierungen abgewiesen.</p><p>PDF→DOCX extrahiert Text und rekonstruiert kein identisches Office-Layout. PDF→PPTX nutzt Seitenbilder. Office- und E-Book-Formate benötigen teilweise LibreOffice oder Pandoc. Ein DOCX-Export startet OCR nicht automatisch. ZIP packt zusammen; Entpacken öffnet ein Archiv in einen neuen Unterordner.</p>'''),
    ('Bilder bearbeiten, drehen & beschriften',f'''<h2>Bildeditor</h2><p>Ein Bild auswählen → <b>{edit} → Bild bearbeiten</b>. Den Ausschnitt mit der Maus ziehen, bei Bedarf ein Seitenverhältnis wählen, das Bild drehen und Helligkeit, Kontrast oder Farben anpassen. Die Vorschau zeigt Änderungen; Originalvergleich und Zurücksetzen helfen beim Prüfen. Die Ausgabegröße wird über Breite/Höhe eingestellt. Export erzeugt eine neue Datei.</p><p>Die direkten Drehaktionen 90° links/rechts und 180° sind für schnelle Aufgaben da. „Bildgröße“ kann auch mehrere Bilder bearbeiten. „Schwärzen & Beschriften“ ergänzt deckende Bereiche, Texte, Pfeile und Rahmen; Elemente lassen sich verschieben oder rückgängig machen. Der Export zeichnet sie fest in die neue Bilddatei. Er ist keine automatische Erkennung vertraulicher Inhalte.</p>'''),
    ('Schwarzweiß, Bitmap & SVG','''<h2>Vom Foto zur Vektorgrafik</h2><p><b>Schwarzweiß</b> erstellt Graustufen oder zwei Farben. <b>Bitmap</b> erzeugt ein echtes 1-Bit-Bild; der Schwellwert-Regler bestimmt, welche Bildbereiche schwarz oder weiß werden. Kontrast und weitere Vorbereitungen lassen sich in der Vorschau abstimmen.</p><p><b>SVG Schnell</b> bereitet das Bild automatisch vor und wandelt es in Vektorpfade um. <b>SVG Erweitert</b> öffnet die Vorschau mit Reglern für Vorbereitung, Konturen/Farben und Glättung. Eine SVG ist keine verlustfreie Rekonstruktion eines Fotos: Hoher Detailgrad kann große Dateien und viele Pfade erzeugen. Für Logos, klare Linien und Stencils zuerst saubere Kontraste und passende Schwellenwerte wählen.</p>'''),
    ('Video- & Audioschnitt',f'''<h2>Abschnitte auswählen und entfernen</h2><p>Eine Video- oder Audiodatei wählen → <b>{edit} → Schneiden</b>. Im Videoeditor zeigen Filmstreifen und Wellenform denselben Zeitbereich; im Audioeditor siehst du die Wellenform. Klicke eine Zeitposition oder einen Abschnitt an.</p><ul><li><b>Leertaste:</b> abspielen / pausieren.</li><li><b>Links / Rechts:</b> im Video frameweise vor/zurück; im Audio um 0,1 Sekunden.</li><li><b>C:</b> Schnittmarke an der aktuellen Position setzen.</li><li><b>Entf:</b> ausgewählten Abschnitt von der Ausgabe ausschließen. Die Wiederherstellen-Schaltfläche nimmt ihn wieder auf.</li><li><b>Shift+Entf:</b> eine ausgewählte Schnittmarke entfernen, nicht den Abschnitt.</li><li><b>Strg+Z / Strg+Y:</b> Schnittänderungen rückgängig / wiederholen.</li></ul><p>Die Zoomleiste reicht von 100 bis 1600 Prozent. Horizontal scrollen oder Einpassen nutzen; beim Abspielen folgt die Ansicht dem Abspielkopf. Videodrehung ist ebenfalls im Editor möglich. Export verbindet die behaltenen Bereiche in einer neuen Datei. Die Quelle bleibt erhalten. Die Vorschau ersetzt keine Kontrolle der fertigen Ausgabe.</p>'''),
    ('Audio verbessern',f'''<h2>Lautheit, Randstille und Fades</h2><p>Audio wählen → <b>{edit} → Audio verbessern</b>. Lautheitsnormalisierung misst in zwei Durchläufen und gleicht an ein Ziel wie −16 oder −23 LUFS an. Die passende Lautheit hängt von deinem Einsatzzweck ab.</p><p>„Stille nur am Anfang und Ende entfernen“ lässt innere Sprechpausen bestehen. Der dB-Regler setzt die Schwelle; ein kleinerer Wert erkennt leisere Töne als Inhalt. Die Randzugabe lässt etwas Abstand. Zu hohe Schwellen können sehr leise Anfänge/Enden entfernen. Ein-/Ausblenden setzt Fades in Sekunden. Sind beide Fades zusammen länger als der verbleibende Ton, wird der Auftrag abgewiesen.</p><p>Ausgabe als neue FLAC-, WAV- oder MP3-Datei. MP3 nutzt 192 kbit/s, die Ausgabe 48 kHz. FFmpeg und FFprobe müssen verfügbar sein.</p>'''),
    ('PDF-Seiten & lokale OCR',f'''<h2>Seitenverwaltung</h2><p>Eine PDF wählen → <b>{edit} → PDF-Seiten</b>. Vorschaubilder auswählen, mit Strg/Shift mehrfach markieren, per Drag-and-drop oder Pfeilen umordnen, drehen, duplizieren oder entfernen. Entf entfernt ausgewählte Seiten; Strg+Z nimmt Änderungen zurück. Export erzeugt eine neue PDF. PDF teilen erstellt einzelne Seiten; PDF verbinden kombiniert mehrere PDFs in ihrer Listenreihenfolge.</p><h2>Texterkennung</h2><p>Ein Bild oder PDF → <b>Text erkennen</b>. Deutsch, Englisch oder beide sowie DPI auswählen. Text lokal erkennen, korrigieren, kopieren oder als neue TXT-Datei speichern. Falls nötig lädt „Deutsch/Englisch einrichten“ nur Sprachdaten herunter; Dokumente werden nicht hochgeladen.</p><p>„Scan-PDF erstellen“ ergänzt eine durchsuchbare Textschicht, rendert die Seiten aber neu. Formulare, Vektoren und interaktive Elemente bleiben darin nicht erhalten. Das Original behalten. Maximal 500 OCR-PDF-Seiten, 50 Megapixel pro Bild/gerenderter Seite und keine verschlüsselten PDFs. Erkannten Text auf Fehler prüfen.</p>'''),
    ('Links, Downloads & Playlists',f'''<h2>Einzelne Dateien herunterladen</h2><p>Einen vollständigen http(s)-Link markieren und <b>{convert}</b> drücken, einen Link in den Kreis ziehen oder <b>{tools} → Link einfügen</b> wählen. Audio oder Video öffnen, Link prüfen und Ausgabeordner wählen. OrbitDrop merkt sich den zuletzt verwendeten Downloadordner unabhängig vom allgemeinen Ausgabeordner.</p><p>Audio wird als MP3 gespeichert. Video verwendet verfügbare Streams; getrennte Bild-/Tonspuren werden als MKV kombiniert. Eine maximale Auflösung lässt sich einstellen. Die Schnittfunktionen erreichst du danach über die gespeicherte Datei.</p><h2>Playlist auswählen</h2><p>Ein YouTube-Playlist-Link oder Video-Link mit Playlist zeigt Titel, bekannte Dauer und Status. Verfügbare Einträge sind zunächst angehakt. Alle auswählen, Keine auswählen oder einzelne Häkchen nutzen. Die Suche filtert nur die Anzeige; unsichtbare markierte Titel bleiben ausgewählt. Der Startbutton zählt die gesamte Auswahl.</p><p>Titel werden nacheinander geladen. Ein Einzelfehler stoppt die übrigen nicht; Details stehen im Verlauf. Abbruch behält fertige Dateien und entfernt den laufenden Teil-Download. Als privat/gelöscht erkannte Einträge sind gesperrt; weitere Sperren können erst beim Abruf auffallen. Private/gesperrte Playlists können nicht ohne passende Berechtigung gelesen werden. Es gibt keine automatische Anmeldung oder Browser-Cookie-Übernahme. Maximal 10.000 Einträge und fünf Minuten für die Prüfung. Unterplaylists werden nicht automatisch erweitert.</p>'''),
    ('Tools · Dateien, ZIP & Ablage',f'''<h2>Dateiaktionen direkt im Kreis</h2><p>Dateien oder Ordner ziehen und <b>{tools}</b> drücken. Je nach Auswahl erscheinen Kopieren, Pfad kopieren, Verschieben, Explorer, Terminal, ZIP, Entpacken, Ablage und Umbenennen.</p><ul><li><b>Kopieren:</b> Dateien in die Windows-Zwischenablage, danach in einer anderen App einfügen.</li><li><b>Pfad:</b> Pfade als Text kopieren.</li><li><b>Terminal:</b> im enthaltenden Ordner öffnen.</li><li><b>ZIP:</b> ausgewählte Dateien/Ordner gemeinsam archivieren.</li><li><b>Entpacken:</b> in einen neuen Unterordner; Originalarchiv bleibt erhalten.</li><li><b>Ablage:</b> Dateien im schwebenden Fenster parken und später in andere Apps ziehen. Leeren löscht nur Ablageeinträge, keine Originaldateien.</li><li><b>Verschieben:</b> versetzt die Originale. Ziel und Vorschau prüfen.</li></ul><p>Bei unbekannten Dateitypen bleiben passende Dateiaktionen verfügbar. Nicht erkannte Typen erscheinen außerdem im Debugging-Menü.</p>'''),
    ('Umbenennen & eigene Bildabläufe','''<h2>Stapel-Umbenennen</h2><p>Dateien → Tools → Umbenennen. Muster wie Urlaub_{n}, {name}_{n}, Startnummer und Ziffern einstellen. Die Dateiendung bleibt erhalten. Vorher-/Nachher-Liste prüfen, dann „Wie angezeigt umbenennen“. Das ändert die Originalnamen. Konflikte, reservierte Windows-Namen und vorhandene Fremddateien werden abgefangen. Letzte Umbenennung kann bis zum Schließen des Fensters zurückgenommen werden, sofern die Dateien unverändert sind. Bei unvollständiger Rücknahme nennt die Fehlermeldung zu prüfende Pfade.</p><h2>Eigene Bildabläufe</h2><p>Tools → Bildabläufe. Schritte hinzufügen, ordnen und unter einem Namen speichern. Möglich sind unter anderem Verkleinern, Drehen, Graustufen, Metadaten entfernen, Komprimierung, Formatwechsel und Ausgaben benennen. Benennen gehört ans Ende. Beispiel: 1600 px → Metadaten entfernen → WebP → Web_{n}. Der Ablauf erscheint für Bilder im Bearbeiten-Kreis. Originale bleiben erhalten; nur fertige neue Ergebnisse werden ausgegeben. Aktuell Einzelbilder, keine Audio-/Videoketten.</p>'''),
    ('Komprimieren & Zielgröße','''<h2>Kleiner speichern mit Vorprüfung</h2><p>Komprimieren zeigt die aktuelle Größe und bei mehreren Dateien die Summe. Der Regler setzt ein Größenlimit pro Datei relativ zur ersten Datei; das MB-Feld erlaubt genaue Eingaben. 0 MB entfernt das Limit. Unterschiedlich große Eingaben bekommen dabei dasselbe absolute Limit.</p><p>Bei Bildern berechnet die Vorschau die tatsächliche Ergebnisgröße. Audio und Video werden auf Dauer und technisch mögliche Bitraten geprüft. Unerreichbare Ziele sperren den Export. Niedrige Bitraten können hörbare/sichtbare Verluste verursachen; die Vorprüfung ist keine Qualitätsgarantie. Ohne Zielgröße ist die Dateigröße einer variablen Videokodierung nicht zuverlässig vorhersehbar. PDF-Komprimierung prüft, ob sich ohne Qualitätsverlust tatsächlich etwas sparen lässt.</p><p>Wiederkehrende Einstellungen als Schnellaktion speichern. Passende Rezepte erscheinen für den jeweiligen Dateityp im Bearbeiten-Kreis und lassen sich ebenfalls ausblenden.</p>'''),
    ('Aufträge, Fehler & Wiederherstellung','''<h2>Fortschritt und Ergebnisse</h2><p>Tools → Aufträge zeigt laufende und zuletzt abgeschlossene Arbeiten. Ergebnis öffnen, Ordner anzeigen, Details oder Abbrechen nutzen. Ein neuer Download bringt den Verlauf wieder nach vorn, auch wenn er minimiert war. Bei mehreren Ausgaben kannst du das gewünschte Ergebnis auswählen.</p><p>Abbrechen stoppt den laufenden Schritt möglichst früh. Fertige Konvertierungen bzw. Playlist-Titel bleiben erhalten; unvollständige Ausgaben werden je nach Werkzeug aufgeräumt. Mehrstufige Bildabläufe und manche Stapel-Exporte räumen ihre selbst erzeugten Ergebnisse bei einem Fehler vollständig auf. Details nennen Fehler, fertige Ergebnisse oder zu prüfende Pfade.</p><p>„Verlauf leeren“ entfernt Einträge, nicht die Ergebnisdateien. Umbenennen/Verschieben sind Originaländerungen und benötigen besondere Aufmerksamkeit. Die Rücknahme im Umbenennen-Fenster ist keine dauerhafte Dateisicherung.</p>'''),
    ('Installation, Konverter & Updates','''<h2>Windows-Paket</h2><p>Das Setup installiert für deinen Benutzer und benötigt keine separat installierte Python-Laufzeit. Es gibt außerdem ein portables ZIP: den gesamten Programmordner behalten. Vor einem manuellen Update OrbitDrop vollständig beenden und das neue Setup installieren. Einstellungen liegen außerhalb des Programmordners. Windows x64 ist das getestete Ziel. Die EXE ist bislang nicht digital signiert.</p><p>FFmpeg/FFprobe und deutsche/englische OCR-Daten werden im Paket mitgeliefert. Für Office-/E-Book-Konvertierungen können LibreOffice oder Pandoc nötig sein. Unter Tools → Konverter die Erkennung prüfen. Pfade im Benutzerprofil, PATH und typische Windows-Installationsorte werden berücksichtigt. OrbitDrop wie den Explorer ohne erhöhte Administratorrechte starten, damit Drag-and-drop funktioniert.</p><h2>Updates</h2><p>Tools → Updates prüft stabile GitHub-Releases. Bei jedem Programmstart wird standardmäßig nach Updates in Chaozz2go/OrbitDrop gesucht. Unter Einstellungen oder Updates lässt sich das ausschalten. Bestehende Installationen erhalten die neue Startprüfung einmalig aktiviert; eine danach gespeicherte Abwahl bleibt erhalten. Die automatische Prüfung benötigt ein öffentliches Repository und ein veröffentlichtes Release; ein Release-Entwurf wird nicht angeboten. Download-Prüfsummen werden beim Laden und vor dem Setup-Start geprüft. Eine Prüfsumme ersetzt keine digitale Signatur. Installieren startet das Setup bewusst und erst, wenn keine Hintergrundaufträge mehr laufen. Im Updatefenster stehen die Änderungen der angebotenen Version; „Änderungsverlauf“ öffnet die installierte Versionshistorie auch ohne Internet. Nach einem Versionswechsel erscheinen die Neuerungen einmal.</p>'''),
    ('Info, Datenschutz & Lizenz',f'''<h2>OrbitDrop {html.escape(VERSION)}</h2><p>Windows-Dateiwerkzeug von Chaozz2go mit radialem Drag-and-drop-Menü für Konvertierung, Medienbearbeitung, Downloads und Dateiaktionen.</p><p>Konvertierungen, Bearbeitungen und OCR laufen lokal. Internet wird für ausdrücklich gestartete Downloads, Sprachdaten-/Konverter-Einrichtung und aktivierte Updateprüfungen verwendet. yt-dlp ruft die von dir gewählten Dienste ab. Es gibt keine eingebaute Telemetrie und keinen automatischen Upload deiner Dokumente.</p><p>Einstellungen und Verlauf: <code>{location}</code>. Der Verlauf enthält Dateipfade und Fehlermeldungen. Debugging-Exporte vor dem Weitergeben auf persönliche Angaben prüfen; ein Export wird nicht automatisch versendet.</p><p>© 2026 Chaozz2go. OrbitDrop-eigener Code: GNU AGPL v3. Weitergabe und Änderungen sind nach den Lizenzbedingungen erlaubt. Es besteht keine Gewährleistung, soweit gesetzlich zulässig. Den vollständigen Text öffnet „Lizenz anzeigen“. Abhängigkeiten haben eigene Bedingungen; Lizenztexte liegen im Paket unter third-party sowie bei FFmpeg/OCR-Daten. Öffentlich sichtbarer Quellcode ist nicht gleichbedeutend mit einem veröffentlichten Binär-Release.</p><p><a href="https://github.com/Chaozz2go/OrbitDrop">Repository, Quellen und Fehlerberichte</a> · <a href="https://github.com/Chaozz2go/OrbitDrop/releases">Windows-Downloads</a></p>''')]

    from help_extra import extra_sections
    sections.extend(extra_sections(values))
    return sections

class HelpDialog(QDialog):
    def __init__(self,prefs,parent=None):
        super().__init__(parent);self.setWindowTitle('OrbitDrop · Anleitung & Info');self.setStyleSheet(EDITOR_STYLE);self.resize(1100,750)
        self.sections=handbook(prefs.values,prefs.root);layout=QVBoxLayout(self);heading(layout,'Anleitung & Info','Bedienung, Werkzeuge und deine aktuelle Belegung · '+VERSION)
        self.query=QLineEdit();self.query.setPlaceholderText('In der gesamten Anleitung suchen …');layout.addWidget(self.query)
        splitter=QSplitter();layout.addWidget(splitter,1);self.topics=QListWidget();self.browser=QTextBrowser();self.browser.setOpenExternalLinks(True);splitter.addWidget(self.topics);splitter.addWidget(self.browser);splitter.setSizes([300,800])
        self.topics.addItems([title for title,_ in self.sections]);self.topics.currentRowChanged.connect(self.show_section);self.query.textChanged.connect(self.filter);self.topics.setCurrentRow(0)
        row=QHBoxLayout();layout.addLayout(row);hint=QLabel('Die Anleitung ist lokal verfügbar. Externe Links werden erst beim Anklicken geöffnet.');hint.setWordWrap(True);layout.addWidget(hint);row.addStretch();manual_button=action_button('Handbuch öffnen');manual_button.clicked.connect(self.open_manual);row.addWidget(manual_button);save_manual=action_button('Handbuch speichern');save_manual.clicked.connect(self.save_manual);row.addWidget(save_manual);history=action_button('Änderungsverlauf');history.clicked.connect(self.show_history);row.addWidget(history);license_button=action_button('Lizenz anzeigen');license_button.clicked.connect(self.show_license);row.addWidget(license_button);close=action_button('Schließen');close.clicked.connect(self.accept);row.addWidget(close)
    def show_section(self,row):
        if row<0:return
        title,body=self.sections[row];self.browser.setHtml('<html><head><style>body{color:#eaf2fc;font-family:Segoe UI;font-size:11pt;line-height:1.45}h2{color:#8ce8c9}p,li{margin-bottom:12px}a{color:#91c9ff}code{color:#ffbe8a}</style></head><body>'+body+'</body></html>')
    def filter(self,text):
        words=text.casefold().split();shown=[]
        for row,(title,body) in enumerate(self.sections):
            content=html.unescape(re.sub('<[^>]+>',' ',title+' '+body)).casefold();visible=all(word in content for word in words);self.topics.item(row).setHidden(not visible)
            if visible:shown.append(row)
        if not shown:self.topics.setCurrentRow(-1);self.browser.setPlainText('Keine passenden Themen. Einen anderen Suchbegriff versuchen.')
        elif self.topics.currentRow() not in shown:self.topics.setCurrentRow(shown[0])

    def show_history(self):
        from changelog_ui import ChangelogDialog
        ChangelogDialog(self).exec()

    def open_manual(self):
        from PySide6.QtCore import QUrl
        from PySide6.QtGui import QDesktopServices
        from PySide6.QtWidgets import QMessageBox
        from changelog import resource_path
        path=resource_path('docs/OrbitDrop-Handbuch.html')
        if not path.is_file():
            QMessageBox.information(self,'Handbuch','Die Handbuchdatei fehlt. Die integrierte Anleitung bleibt vollständig verfügbar.');return
        if not QDesktopServices.openUrl(QUrl.fromLocalFile(str(path))):
            QMessageBox.warning(self,'Handbuch','Die Datei konnte nicht geöffnet werden. Du kannst sie mit „Handbuch speichern“ an einem anderen Ort ablegen.')

    def save_manual(self):
        from PySide6.QtWidgets import QFileDialog,QMessageBox
        from changelog import resource_path
        filename,_=QFileDialog.getSaveFileName(self,'Offline-Handbuch speichern','OrbitDrop-Handbuch.html','HTML-Datei (*.html)')
        if not filename:return
        try:
            source=resource_path('docs/OrbitDrop-Handbuch.html')
            Path(filename).write_bytes(source.read_bytes())
        except OSError as error:QMessageBox.warning(self,'Handbuch',str(error))

    def show_license(self):
        dialog=QDialog(self);dialog.setWindowTitle('OrbitDrop · GNU AGPL v3');dialog.resize(850,650);layout=QVBoxLayout(dialog);text=QTextEdit();text.setReadOnly(True);layout.addWidget(text)
        path=Path(getattr(sys,'_MEIPASS',Path(__file__).resolve().parent))/'LICENSE'
        try:text.setPlainText(path.read_text(encoding='utf-8'))
        except OSError:text.setPlainText('Lizenztext nicht gefunden. Die vollständige Lizenz steht im Repository unter LICENSE. https://github.com/Chaozz2go/OrbitDrop/blob/main/LICENSE')
        close=action_button('Schließen');close.clicked.connect(dialog.accept);layout.addWidget(close);dialog.exec()
